head.script:
scwin.screenId = "jldfil00034";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_isurCd", fn: function () { return String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["isurCd"] ?? ""); } },
        { childId: "ipt_fssUnqNo", fn: function () { return String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["fssUnqNo"] ?? ""); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil00034.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.img_79_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.img_79_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin img_79_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.findCompany()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil00034.img_79_onclick' }); }
};

/**
 * @event
 * @name scwin.img_101_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.img_101_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin img_101_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.goWrite()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil00034.img_101_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_documentWrite
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_documentWrite = async function () {
    const sbmOptions = {
        id: "tx_fn_documentWrite",
        method: "post",
        action: "/submission/disclosure.do?method=searchDisclosureDocument",
        ref: "dma_documentWriteReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil00034.tx_fn_documentWrite" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fn_goWrite
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_goWrite = async function () {
    const sbmOptions = {
        id: "tx_fn_goWrite",
        method: "post",
        action: "/submission/disclosurereg.do?method=registerDisclosure",
        ref: "dma_goWriteReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil00034.tx_fn_goWrite" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.findCompany
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.findCompany = async function () {
    /* sdd-asis-lifecycle:begin fn_findCompany — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const corpSearchURL = '/jldfil00035/jldfil00035.xml';
    await $c.win.openPopup((function (__u) { var __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(corpSearchURL), { id: "drvIsuListWin", scrollbars: false, resizable: false, width: "590", height: "570", type: "pageFramePopup" }, { method: "loadInitPageForDrv" });
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.setCorpInfo
 * @author Inswave
 * @date 2026. 09. 29
 * @param isurCd kisComCd repIsuSrtCd comNm comAbbrv isurSymbl fssUnqNo
 * @returns
 * @hidden N
*/
scwin.setCorpInfo = function (isurCd, kisComCd, repIsuSrtCd, comNm, comAbbrv, isurSymbl, fssUnqNo) {
    /* sdd-asis-lifecycle:begin setCorpInfo — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent("ipt_txtisurCd").setValue(isurCd);
    $c.util.getComponent("ipt_txtfssUnqNo").setValue(fssUnqNo);
    $c.util.getComponent("ipt_txtcomNm").setValue(comNm);
    $c.util.getComponent("dma_documentWriteReq").set("tgtIsuSrtCd", repIsuSrtCd);
    $c.util.getComponent("dma_documentWriteReq").set("tgtIsuSrtCd", repIsuSrtCd);
    $c.util.getComponent('dma_documentWriteReq').set('chkPop', 'Y');
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.documentWrite
 * @author Inswave
 * @date 2026. 09. 29
 * @param exmptObjDisclsYn
 * @returns
 * @hidden N
*/
scwin.documentWrite = async function (exmptObjDisclsYn) {
    /* sdd-asis-lifecycle:begin fn_documentWrite — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('dma_documentWriteReq').set('exmptObjDisclsYn', exmptObjDisclsYn);
    (document.corpForm || { elements: [] }).action = '/submission/disclosure.do?method=searchDisclosureDocument';
    await scwin.tx_fn_documentWrite();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.registerProcess
 * @author Inswave
 * @date 2026. 09. 29
 * @param applNo docNo formCd formVer wrtrptMaindocTpCd method exmptObjDisclsYn
 * @returns
 * @hidden N
*/
scwin.registerProcess = async function (applNo, docNo, formCd, formVer, wrtrptMaindocTpCd, method, exmptObjDisclsYn) {
    /* sdd-asis-lifecycle:begin fn_registerProcess — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('dma_documentWriteReq').set('applNo', applNo);
    if (applNo.length == 14) {
        await scwin.documentWrite(exmptObjDisclsYn);
    } else {
        await scwin.registerMessage('문서불러오기에 실패하였습니다. 잠시후 다시 해주시기 바랍니다.');
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.registerMessage
 * @author Inswave
 * @date 2026. 09. 29
 * @param msg
 * @returns
 * @hidden N
*/
scwin.registerMessage = async function (msg) {
    /* sdd-asis-lifecycle:begin registerMessage — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    await $c.win.alert(msg);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.goWrite
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.goWrite = async function () {
    /* sdd-asis-lifecycle:begin fn_goWrite — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (($c.util.getComponent('ipt_txtisurCd').getValue() == null ? '' : String($c.util.getComponent('ipt_txtisurCd').getValue())) === '' || $c.util.getComponent('dma_goWriteReq').get('tgtIsuCd')=== '' || ($c.util.getComponent('ipt_txtcomNm').getValue() == null ? '' : String($c.util.getComponent('ipt_txtcomNm').getValue())) === '' || $c.util.getComponent('dma_documentWriteReq').get('chkPop') === '') {
        await $c.win.alert('대상 종목을 선택하십시요');
        return;
    }
    $c.util.getComponent('dma_documentWriteReq').set('tgtIsurCd', $c.util.getComponent('ipt_txtisurCd').getValue());
    $c.util.getComponent("dma_documentWriteReq").set("tgtIsuSrtCd", $c.util.getComponent("dma_documentWriteReq").get("tgtIsuSrtCd"));
    $c.util.getComponent('dma_documentWriteReq').set('tgtFssUnqNo', $c.util.getComponent('ipt_txtfssUnqNo').getValue());
    $c.util.getComponent('dma_documentWriteReq').set('tgtComNm', $c.util.getComponent('ipt_txtcomNm').getValue());
    $c.util.getComponent('dma_documentWriteReq').set('tgtIsurCd', $c.util.getComponent('ipt_txtisurCd').getValue());
    $c.util.getComponent("dma_documentWriteReq").set("tgtIsuSrtCd", $c.util.getComponent("dma_documentWriteReq").get("tgtIsuSrtCd"));
    $c.util.getComponent('dma_documentWriteReq').set('tgtFssUnqNo', $c.util.getComponent('ipt_txtfssUnqNo').getValue());
    $c.util.getComponent('dma_documentWriteReq').set('tgtComNm', $c.util.getComponent('ipt_txtcomNm').getValue());
    $c.util.getComponent('dma_documentWriteReq').set('exmptObjDisclsYn', '' + dma_disclosureVo.get("exmptObjDisclsYn") + '');
    (document.disclosureFrm || { elements: [] }).action = '/submission/disclosurereg.do?method=registerDisclosure';
    (document.disclosureFrm || { elements: [] }).target = 'tempSaveFrame';
    await scwin.tx_fn_goWrite();
    /* sdd-asis-lifecycle:end */
};
